135	HcclResult
136	CheckAllReduceInputPara(const HcclComm comm, const void* sendBuf, const void* recvBuf, const aclrtStream stream)
137	{
138	    // 入参合法性校验
139	    RPT_INPUT_ERR(
140	        stream == nullptr, "EI0003", std::vector<std::string>({"ccl_op", "value", "parameter", "expect"}),
141	        std::vector<std::string>({"HcclAllReduce", "nullptr", "stream", "non-null pointer"}));
142	    CHK_PTR_NULL(stream);
143	    RPT_INPUT_ERR(
144	        comm == nullptr, "EI0003", std::vector<std::string>({"ccl_op", "value", "parameter", "expect"}),
145	        std::vector<std::string>({"HcclAllReduce", "nullptr", "comm", "non-null pointer"}));
146	    CHK_PTR_NULL(comm);
147	    RPT_INPUT_ERR(
148	        sendBuf == nullptr, "EI0003", std::vector<std::string>({"ccl_op", "value", "parameter", "expect"}),
149	        std::vector<std::string>({"HcclAllReduce", "nullptr", "sendBuf", "non-null pointer"}));
150	    CHK_PTR_NULL(sendBuf);
151	    RPT_INPUT_ERR(
152	        recvBuf == nullptr, "EI0003", std::vector<std::string>({"ccl_op", "value", "parameter", "expect"}),
153	        std::vector<std::string>({"HcclAllReduce", "nullptr", "recvBuf", "non-null pointer"}));
154	    CHK_PTR_NULL(recvBuf);
155	
156	    return HCCL_SUCCESS;
157	}
